-- CAPEX-S2-HEALTH-OVERDUE (bim-ootb prompts/CAPEX_DASHBOARD.md §5.44): Project Health is never Green while a phase is overdue (IsComplete='N' AND EndDate < today): such a project is Amber. Green gains AND NOT overdue; Amber gains OR (Green's test AND overdue). Red unchanged.
-- Restore: re-apply the WhereClause of 202611032200_CAPEX-G4.sql for PA_MeasureCalc 1000023 and 1000024.
SELECT register_migration_script('202611121000_CAPEX-S2-HEALTH-OVERDUE.sql') FROM dual;

UPDATE PA_MeasureCalc SET WhereClause='WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND TRUNC(ph.EndDate)<=TRUNC(SYSDATE))>0 AND (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')>=0.9*(SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND TRUNC(ph.EndDate)<=TRUNC(SYSDATE)) AND (COALESCE(p.ProjectBalanceAmt,0)<=0 OR (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')>=0.9*COALESCE(p.ProjectBalanceAmt,0)) AND NOT EXISTS (SELECT 1 FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''N'' AND ph.EndDate IS NOT NULL AND TRUNC(ph.EndDate)<TRUNC(SYSDATE))', Updated=TO_TIMESTAMP('2026-11-12 10:00:00','YYYY-MM-DD HH24:MI:SS') WHERE PA_MeasureCalc_ID=1000023;
